import math

def count_admissible(R, C, K):
    S = 1 << R
    pop = [s.bit_count() for s in range(S)]
    mask = (1 << R) - 1
    # Precompute adjacency lists for compatible consecutive columns
    adj = [[] for _ in range(S)]
    adj_bits = [ (s & ((s << 1) & mask)) for s in range(S) ]
    for prev in range(S):
        ap = adj_bits[prev]
        for curr in range(S):
            ac = adj_bits[curr]
            if (ap & ac) == 0:
                adj[prev].append(curr)
    # DP over columns counting admissible matrices with exactly K ones
    dp = [[0]*(K+1) for _ in range(S)]
    for s in range(S):
        c = pop[s]
        if c <= K:
            dp[s][c] = 1
    for _ in range(1, C):
        new = [[0]*(K+1) for _ in range(S)]
        for prev in range(S):
            rowcounts = dp[prev]
            for c in range(K+1):
                val = rowcounts[c]
                if not val:
                    continue
                for curr in adj[prev]:
                    cc = c + pop[curr]
                    if cc <= K:
                        new[curr][cc] += val
        dp = new
    Ak = sum(dp[s][K] for s in range(S))
    return Ak

# Try multiple times to find a valid, nontrivial instance
for _ in range(100):
    rows = rng.randint(5, 7)
    cols = rng.randint(5, 8)
    nm = rows * cols
    p_den = rng.randint(3, 9)
    # Choose p_num coprime to p_den
    p_candidates = [i for i in range(1, p_den) if math.gcd(i, p_den) == 1]
    p_num = rng.choice(p_candidates)
    lo = int(math.ceil(0.35 * nm))
    hi = int(math.floor(0.65 * nm))
    if lo < 1:
        lo = 1
    if hi > nm - 1:
        hi = nm - 1
    if lo > hi:
        lo, hi = 1, nm - 2
    k = rng.randint(lo, hi)
    Ak = count_admissible(rows, cols, k)
    if Ak > 0:
        return {'rows': rows, 'cols': cols, 'p_num': p_num, 'p_den': p_den, 'k': k}
# Fallback deterministic instance if random tries fail (highly unlikely)
rows, cols = 5, 5
nm = rows * cols
p_den, p_num = 3, 1
# Find a k that yields a nonzero count
for k in range(1, nm - 1):
    if count_admissible(rows, cols, k) > 0:
        return {'rows': rows, 'cols': cols, 'p_num': p_num, 'p_den': p_den, 'k': k}
# As an ultimate fallback (extremely unlikely), select mid k
return {'rows': rows, 'cols': cols, 'p_num': p_num, 'p_den': p_den, 'k': nm//2}

